// Analyze the provided network scan result for anomalies

/**
 * @param {any} data - The input JSON object containing scan details.
 */

function analyzeScanResult(data) {
  // Extract target and open ports from the scan result
  const targets = data.target.split(' ');
  const openPorts = data.openPorts.map(port => port.toString());

  // Create a map of host to open ports
  const hostsOpenToPings = {};
  targets.forEach(target => {
    if (openPorts.includes(target)) {
      hostsOpenToPings[target] = true;
    }
  });

  return {targets, hostsOpenToPings};
}

// Example usage:
const scanResultData = {
  target: "127.0.0.1",
  openPorts: [135, 445],
  timestamp: "2026-05-10T03:05:04.543Z",
  scanMethod: "native-net"
};

const result = analyzeScanResult(scanResultData);
console.log(result); // Output the analyzed data
```

